mapper.update:
UPDATE sd_user_model
SET publish_status=#{publishStatus}
  ,is_user_del=#{isUserDel}
  ,model_strength=#{modelStrength}
WHERE id=#{id}

mapper.select:
select id,config,addition_tag AS additionTag
FROM sd_user_model
WHERE id IN #{id}

select id AS taskId,pre_param AS preParam
FROM sd_train_task
WHERE id IN #{taskId}
